using System.Diagnostics;
using System.Net;
using System.Net.Http.Headers;
using System.Text.Json;
using FluentAssertions;
using Microsoft.Data.SqlClient;
using Testcontainers.MsSql;
using Xrmd.Cli.Auth;
using Xrmd.Cli.Config;
using Xrmd.TestSupport;
using Xunit.Abstractions;

namespace Xrmd.Integration.Tests;

/// <summary>
/// Plan 9 (item 2.17) end to end, without the xrmd image (ruling M9): the installation is generated by the real
/// <c>xrmd server init</c> and resolved by the real <c>docker compose config</c>; each <c>xrmd-&lt;org&gt;</c> service then
/// runs as an <c>Xrmd.Host</c> process with that service's resolved environment. The emulation changes only what the
/// container runtime would provide:
/// <list type="bullet">
/// <item><c>Server=</c> of <c>ConnectionStrings__Org</c> points at the Testcontainers SQL Server, which is started with
/// the <c>SA_PASSWORD</c> of the generated <c>.env</c> (so the user and password are the generated ones);</item>
/// <item><c>ASPNETCORE_URLS</c> listens on the service's published host port (the port mapping to container port 5000);</item>
/// <item><c>Files__FileSystem__Root</c> is a temporary directory (the <c>files</c> volume at <c>/var/lib/xrmd/files</c>).</item>
/// </list>
/// A real <c>xrmd server up</c> with the published image is checked by hand.
/// </summary>
[Trait("Category", "Acceptance")]
public sealed class MultiOrgAcceptanceTests(ITestOutputHelper output) : IAsyncLifetime
{
    private readonly string _root = Path.Combine(Path.GetTempPath(), "xrmd-multiorg-acceptance", Guid.NewGuid().ToString("N"));
    private readonly List<HostProcess> _hosts = [];
    private readonly HttpClient _http = new() { Timeout = TimeSpan.FromSeconds(30) };
    private MsSqlContainer? _sql;

    private static void CopyDirectory(string from, string to)
    {
        Directory.CreateDirectory(to);
        foreach (var file in Directory.GetFiles(from)) File.Copy(file, Path.Combine(to, Path.GetFileName(file)), true);
    }

    private string InstallDir => Path.Combine(_root, "install");
    private string ConfigDir => Path.Combine(_root, "config");
    private string FilesRoot => Path.Combine(_root, "files");

    private string _hostFolder = "";
    private string _sdk = "";

    /// <summary>The published host (no Microsoft SDK in it, its own deps.json) and an SDK folder installed from the cached package (Plan 12).</summary>
    public async Task InitializeAsync()
    {
        _hostFolder = await PublishedApps.HostAsync();
        _sdk = await PublishedApps.InstalledSdkAsync();
    }

    public async Task DisposeAsync()
    {
        foreach (var host in _hosts) host.Dispose();
        _http.Dispose();
        if (_sql is not null) await _sql.DisposeAsync();
        try { Directory.Delete(_root, recursive: true); } catch (DirectoryNotFoundException) { }
        PublishedApps.DeleteFolder(_sdk);
    }

    private static string LockMessage(string database) =>
        $"Another xrmd process already serves the database '{database}' (applock 'xrmd-instance' is held). Run one xrmd process per organization database.";

    [Fact]
    public async Task Two_organizations_on_one_sql_server_then_a_third_added_without_touching_them()
    {
        // 1. `server init --org acme --org zenith`: two services on 5001/5002, two databases.
        var cli = new MultiOrgCli(ConfigDir);
        (await cli.RunAsync("server", "init", "--accept-sql-server-eula", "--dir", InstallDir, "--org", "acme", "--org", "zenith")).Should().Be(0, cli.Err);
        var env = ReadEnv();
        env["XRMD_ORGS"].Should().Be("acme,zenith");
        env["ORG_ACME_PORT"].Should().Be("5001");
        env["ORG_ZENITH_PORT"].Should().Be("5002");
        cli.SigningKey = env["AUTH_DEV_SIGNING_KEY"]; // the profiles sign with XRMD_DEV_SIGNING_KEY = AUTH_DEV_SIGNING_KEY

        _sql = new MsSqlBuilder("mcr.microsoft.com/mssql/server:2022-latest").WithPassword(env["SA_PASSWORD"]).Build();
        await _sql.StartAsync();

        var services = await ResolvedServicesAsync();
        services.Keys.Where(k => k.StartsWith("xrmd-", StringComparison.Ordinal)).Should().BeEquivalentTo(["xrmd-acme", "xrmd-zenith"]);
        var acme = StartHost("acme", services["xrmd-acme"]);
        var zenith = StartHost("zenith", services["xrmd-zenith"]);
        await Task.WhenAll(WaitHealthyAsync(acme), WaitHealthyAsync(zenith));
        acme.Port.Should().Be(5001);
        zenith.Port.Should().Be(5002);
        (await DatabasesAsync()).Should().Contain(["acme", "zenith"]);

        // 2. WhoAmI through each profile; an acme token sent to zenith is refused (audiences differ, M4).
        var config = new ProfileStore(ConfigDir).Load();
        config.CurrentProfile.Should().Be("acme");
        var acmeOrgId = await WhoAmIOrganizationAsync(cli, "acme");
        var zenithOrgId = await WhoAmIOrganizationAsync(cli, "zenith");
        acmeOrgId.Should().NotBe(zenithOrgId, "each organization is its own database");

        var acmeToken = await new DevTokenProvider(config.Profiles["acme"], cli.Env()).GetTokenAsync(CancellationToken.None);
        (await WhoAmIStatusAsync("http://localhost:5001/", acmeToken)).Should().Be(HttpStatusCode.OK);
        (await WhoAmIStatusAsync("http://localhost:5002/", acmeToken)).Should().Be(HttpStatusCode.Unauthorized);

        // 3. A third process on acme's database fails startup with the explicit error; acme keeps serving.
        var intruder = StartHost("acme-second", services["xrmd-acme"], port: 5091);
        (await intruder.WaitForExitAsync(TimeSpan.FromMinutes(3))).Should().BeTrue("the refused process exits\n" + intruder.Output);
        intruder.ExitCode.Should().NotBe(0);
        intruder.Output.Should().Contain(LockMessage("acme"));
        (await HealthzAsync(acme)).Should().Be(HttpStatusCode.OK);
        (await WhoAmIOrganizationAsync(cli, "acme")).Should().Be(acmeOrgId);

        // 4. `server org add orbit`: only xrmd-orbit is started; acme and zenith are untouched.
        var acmeStart = acme.StartTime;
        var zenithStart = zenith.StartTime;
        using var watch = new HealthWatch([.. new[] { acme, zenith }.Select(h => (h.Name, _http, $"http://localhost:{h.Port}/healthz"))]);

        var docker = new RecordingProcessRunner();
        cli.Process = docker;
        // `org add` refuses to start containers without <dir>/sdk/sdk.json: the customer's SDK, installed here from the cached package.
        CopyDirectory(_sdk, Path.Combine(InstallDir, "sdk"));
        (await cli.RunAsync("server", "org", "add", "orbit", "--dir", InstallDir)).Should().Be(0, cli.Err);
        docker.Calls.Should().ContainSingle();
        docker.Calls[0].FileName.Should().Be("docker");
        docker.Calls[0].Arguments.TakeLast(3).Should().Equal("up", "-d", "xrmd-orbit");

        var after = await ResolvedServicesAsync();
        foreach (var name in new[] { "xrmd-acme", "xrmd-zenith" })
            after[name].GetRawText().Should().Be(services[name].GetRawText(), $"{name} keeps its exact configuration, so Compose has no reason to recreate it");
        ReadEnv()["ORG_ORBIT_PORT"].Should().Be("5003");

        var orbit = StartHost("orbit", after["xrmd-orbit"]);
        await WaitHealthyAsync(orbit);
        orbit.Port.Should().Be(5003);
        (await DatabasesAsync()).Should().Contain(["acme", "zenith", "orbit"]);
        (await WhoAmIOrganizationAsync(cli, "orbit")).Should().NotBe(acmeOrgId).And.NotBe(zenithOrgId);

        var failures = await watch.StopAsync();
        failures.Should().BeEmpty("acme and zenith answer /healthz throughout");
        watch.Probes.Should().BeGreaterThan(0);
        foreach (var (host, start) in new[] { (acme, acmeStart), (zenith, zenithStart) })
        {
            host.HasExited.Should().BeFalse($"{host.Name} keeps running");
            Process.GetProcessById(host.Id).StartTime.Should().Be(start, $"{host.Name} was not restarted");
        }

        // `server status` reports every organization of the installation.
        cli.Process = new RecordingProcessRunner();
        (await cli.RunAsync("server", "status", "--dir", InstallDir, "-o", "json")).Should().Be(0, cli.Err + cli.Out);
        using var status = JsonDocument.Parse(cli.Out);
        status.RootElement.EnumerateArray()
            .Select(e => (e.GetProperty("org").GetString(), e.GetProperty("url").GetString(), e.GetProperty("health").GetProperty("status").GetString()))
            .Should().Equal(
                ("acme", "http://localhost:5001/", "Healthy"),
                ("zenith", "http://localhost:5002/", "Healthy"),
                ("orbit", "http://localhost:5003/", "Healthy"));

        // 5. A process whose lock is taken by another after a loss stops with a non-zero exit code (a failure for a
        //    supervisor, not a graceful stop).
        await using (var admin = new SqlConnection(_sql!.GetConnectionString()))
        {
            await admin.OpenAsync();
            await using var find = new SqlCommand(
                "SELECT TOP (1) request_session_id FROM sys.dm_tran_locks WHERE resource_type = 'APPLICATION' AND resource_database_id = DB_ID('orbit')",
                admin);
            var spid = Convert.ToInt32(await find.ExecuteScalarAsync());
            await using var kill = new SqlCommand($"KILL {spid}", admin);
            await kill.ExecuteNonQueryAsync();
        }
        await using var taker = new SqlConnection(new SqlConnectionStringBuilder(_sql.GetConnectionString())
        {
            InitialCatalog = "orbit",
            Pooling = false,
        }.ConnectionString);
        await taker.OpenAsync();
        await using (var take = new SqlCommand(
            "DECLARE @r int; EXEC @r = sp_getapplock @Resource = N'xrmd-instance', @LockMode = N'Exclusive', @LockOwner = N'Session', @LockTimeout = 0; SELECT @r;",
            taker))
            (Convert.ToInt32(await take.ExecuteScalarAsync())).Should().BeGreaterOrEqualTo(0, "the lock is free once its session is killed");
        (await orbit.WaitForExitAsync(TimeSpan.FromMinutes(2))).Should().BeTrue("orbit lost its lock to another process\n" + orbit.Output);
        orbit.ExitCode.Should().Be(1, orbit.Output);
        (await HealthzAsync(acme)).Should().Be(HttpStatusCode.OK, "the other organizations are not affected");
    }

    private Dictionary<string, string> ReadEnv() => MultiOrgHarness.ReadEnv(InstallDir);

    private Task<Dictionary<string, JsonElement>> ResolvedServicesAsync() => MultiOrgHarness.ResolvedServicesAsync(InstallDir);

    /// <summary>Starts <c>Xrmd.Host</c> with the resolved environment of a compose service (see the class remarks for what is emulated).</summary>
    private HostProcess StartHost(string name, JsonElement service, int? port = null)
    {
        var published = int.Parse(service.GetProperty("ports")[0].GetProperty("published").GetString()!, System.Globalization.CultureInfo.InvariantCulture);
        service.GetProperty("ports")[0].GetProperty("target").GetInt32().Should().Be(5000);
        var listen = port ?? published;
        var host = MultiOrgHarness.StartHost(name, listen, service, _hostFolder,
            new SqlConnectionStringBuilder(_sql!.GetConnectionString()).DataSource, $"http://127.0.0.1:{listen}", FilesRoot, _sdk, output);
        _hosts.Add(host);
        return host;
    }

    private async Task<HttpStatusCode?> HealthzAsync(HostProcess host)
    {
        try
        {
            return (await _http.GetAsync($"http://localhost:{host.Port}/healthz")).StatusCode;
        }
        catch (HttpRequestException)
        {
            return null;
        }
    }

    private async Task WaitHealthyAsync(HostProcess host)
    {
        var deadline = DateTime.UtcNow + TimeSpan.FromMinutes(4);
        while (DateTime.UtcNow < deadline)
        {
            if (host.HasExited) throw new Xunit.Sdk.XunitException($"{host.Name} exited with {host.ExitCode}:\n{host.Output}");
            if (await HealthzAsync(host) == HttpStatusCode.OK) return;
            await Task.Delay(500);
        }
        throw new Xunit.Sdk.XunitException($"{host.Name} did not answer /healthz:\n{host.Output}");
    }

    private async Task<List<string>> DatabasesAsync()
    {
        await using var conn = new SqlConnection(_sql!.GetConnectionString());
        await conn.OpenAsync();
        await using var cmd = new SqlCommand("SELECT name FROM sys.databases", conn);
        await using var reader = await cmd.ExecuteReaderAsync();
        var names = new List<string>();
        while (await reader.ReadAsync()) names.Add(reader.GetString(0));
        return names;
    }

    /// <summary><c>xrmd auth status --profile &lt;org&gt;</c> (WhoAmI through the profile created for the org): its OrganizationId.</summary>
    private static async Task<string> WhoAmIOrganizationAsync(MultiOrgCli cli, string profile)
    {
        (await cli.RunAsync("auth", "status", "--profile", profile, "-o", "json")).Should().Be(0, cli.Err);
        using var doc = JsonDocument.Parse(cli.Out);
        var json = doc.RootElement.ValueKind == JsonValueKind.Array ? doc.RootElement[0] : doc.RootElement;
        json.GetProperty("profile").GetString().Should().Be(profile);
        return json.GetProperty("organizationId").GetString()!;
    }

    private async Task<HttpStatusCode> WhoAmIStatusAsync(string baseUrl, string token)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get, baseUrl + "api/data/v9.2/WhoAmI");
        request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
        return (await _http.SendAsync(request)).StatusCode;
    }
}
